INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (12976, 'WHO Warns Congo Ebola Outbreak Could Be Deadliest On Record', 'WHO ने चेताया, कांगो में इबोला का प्रकोप रिकॉर्ड के सबसे घातक प्रकोपों में से एक हो सकता है', 'The World Health Organization (WHO) has warned that the Ebola outbreak in the Democratic Republic of Congo (DRC) could become the deadliest on record. As of recent reports, the number of confirmed cases has risen to 4,449, with the death toll surpassing 2,000. Officials state the virus is spreading rapidly, with the WHO indicating it is "chasing" the outbreak and that the virus is "ahead of us." A study suggests that new transmissions from animals likely caused the Congo-Uganda Ebola outbreak. The outbreak was officially declared on May 15 but is believed to have been spreading for several weeks prior.', 'विश्व स्वास्थ्य संगठन (WHO) ने चेतावनी दी है कि कांगो लोकतांत्रिक गणराज्य (DRC) में इबोला का प्रकोप रिकॉर्ड के सबसे घातक प्रकोपों में से एक बन सकता है। हालिया रिपोर्टों के अनुसार, पुष्ट मामलों की संख्या बढ़कर 4,449 हो गई है, और मरने वालों की संख्या 2,000 से अधिक हो गई है। अधिकारियों का कहना है कि वायरस तेजी से फैल रहा है, और WHO ने संकेत दिया है कि वे प्रकोप का "पीछा" कर रहे हैं और वायरस "हमारे आगे" है। एक अध्ययन से पता चलता है कि जानवरों से नए संचरण ने कांगो-युगांडा इबोला प्रकोप का कारण बनने की संभावना है। प्रकोप को 15 मई को घोषित किया गया था, लेकिन माना जाता है कि यह पहले से ही कई हफ्तों से फैल रहा था।', '["The WHO has warned the Ebola outbreak in DR Congo could become the deadliest on record.", "Confirmed cases have reached 4,449, with over 2,000 deaths reported.", "WHO officials describe the situation as the virus being ahead of their efforts.", "A study suggests animal transmission as a likely cause for the Congo-Uganda outbreak.", "The outbreak, declared May 15, is believed to have been spreading for weeks before."]'::jsonb, '["WHO ने चेतावनी दी है कि DR कांगो में इबोला का प्रकोप रिकॉर्ड के सबसे घातक प्रकोपों में से एक हो सकता है।", "पुष्ट मामलों की संख्या 4,449 हो गई है, जिसमें 2,000 से अधिक मौतें दर्ज की गई हैं।", "WHO अधिकारियों ने स्थिति का वर्णन करते हुए कहा है कि वायरस उनके प्रयासों से आगे है।", "एक अध्ययन से पता चलता है कि जानवरों से संचरण कांगो-युगांडा प्रकोप का संभावित कारण है।", "15 मई को घोषित प्रकोप, इससे पहले कई हफ्तों से फैल रहा माना जाता है।"]'::jsonb, 'Health', 'World', 5, 16, 1, 0, 0, 47, 'center', 73, NULL, NULL, '{"left": {"count": 5, "sources": ["Al Jazeera English", "CNN", "National Herald", "The Guardian", "The Independent"], "owners": ["Al Jazeera English", "CNN", "National Herald", "The Guardian", "The Independent"]}, "center": {"count": 16, "sources": ["Associated Press", "BBC News", "CBC News", "Channel News Asia", "Deutsche Welle", "Euronews", "Global News (Canada)", "Irish Independent", "Le Monde", "NBC News", "NPR", "Reuters", "Sky News", "The Economic Times", "The Print", "Toronto Star"], "owners": ["Associated Press", "BBC News", "CBC News", "Channel News Asia", "Deutsche Welle", "Euronews", "Global News (Canada)", "Irish Independent", "Le Monde", "NBC News", "NPR", "Reuters", "Sky News", "The Print", "Times Group", "Toronto Star"]}, "right": {"count": 1, "sources": ["Republic World"], "owners": ["Republic World"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["The sole left-leaning outlet emphasizes the WHO''s warning that the outbreak could become the deadliest on record."], "center": ["Centrist coverage highlights the rising number of confirmed cases, reaching 4,449.", "Centrist outlets also report on a study suggesting animal transmission as a likely cause of the outbreak."], "right": ["The sole right-leaning outlet highlights the WHO Chief''s statement that the outbreak is on track to surpass the deadliest one in history."]}'::jsonb, '{"left": ["एकमात्र वाम-झुकाव वाले आउटलेट ने WHO की इस चेतावनी पर जोर दिया है कि प्रकोप रिकॉर्ड के सबसे घातक प्रकोपों में से एक हो सकता है।"], "center": ["मध्यमार्गी कवरेज में पुष्ट मामलों की बढ़ती संख्या पर प्रकाश डाला गया है, जो 4,449 तक पहुंच गई है।", "मध्यमार्गी आउटलेट प्रकोप के संभावित कारण के रूप में पशु संचरण का सुझाव देने वाले एक अध्ययन की भी रिपोर्ट करते हैं।"], "right": ["एकमात्र दक्षिणपंथी आउटलेट ने WHO प्रमुख के इस बयान पर प्रकाश डाला है कि प्रकोप इतिहास के सबसे घातक प्रकोपों को पार करने की राह पर है।"]}'::jsonb, '[{"source": "The Independent", "owner": "The Independent", "lean": "left", "language": "en", "url": "https://news.google.com/rss/articles/CBMiqAFBVV95cUxNblktNlBkZkYtNDBMN2dDMU1UeVZSTW1tUkdVZW5QV25Odk11UVM2VmNPZmVJQzFBNEZ6d1Jfc1pOWk5SSDBtOU1uUUFmbm54T1lEZ0MtYlduaEJQUDk4V2p6TE02TkMwQ1dTaDlYTDRmQ3V1cDZSeFBCelZZbmNYaG1MZ2JCX1ZXNVFKbW05QlkzMVVxYTBwcWtLSEw0V2RCeWNZQkdhb08?oc=5", "headline": "WHO warns it is ‘chasing’ Ebola as death toll surpasses 1,900: ‘The virus is ahead of us’"}, {"source": "Le Monde", "owner": "Le Monde", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Ebola death toll in DR Congo outbreak rises to more than 2,000"}, {"source": "CBC News", "owner": "CBC News", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMie0FVX3lxTFBXajZEbHU0Um9RbUZKM2hvMVRwc1MyOFJNVjJnWl9fLXhwTk9qMlhwUzM4bDVDZndnOE1TbGRwN1JibEtHS3R6WXdDZkNsc1FzQmxVcXNmZW84VUdqekR2NnY0YnFwZVNrR2tpU3o1WERVNFBxZ09jNWh5VQ?oc=5", "headline": "Congo battles fastest-spreading Ebola outbreak on record as deaths top 2,000"}, {"source": "NBC News", "owner": "NBC News", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMiswFBVV95cUxQN3dvQW8yM3F4U3pCbURFam5tbG12TGVKUWVIb0NGa3pCRENOVDhI