INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (12977, 'Meta CEO Zuckerberg Unveils Open-Source AI Vision', 'मेटा सीईओ ज़करबर्ग ने ओपन-सोर्स AI विजन का अनावरण किया', 'Meta CEO Mark Zuckerberg has outlined his company''s vision for artificial intelligence, emphasizing an open-source approach. Meta has released a new AI model, Muse Glimmer 30B, designed for developers and capable of running on personal computers. Zuckerberg stated that AI will not eliminate jobs and predicted that small businesses will benefit from its integration. He also expressed a desire for "superintelligence for all" and suggested AI could be more intimate than existing assistants.', 'मेटा के सीईओ मार्क ज़करबर्ग ने कृत्रिम बुद्धिमत्ता के लिए अपनी कंपनी के विजन की रूपरेखा तैयार की है, जिसमें ओपन-सोर्स दृष्टिकोण पर जोर दिया गया है। मेटा ने डेवलपर्स के लिए एक नया AI मॉडल, Muse Glimmer 30B जारी किया है, जो व्यक्तिगत कंप्यूटरों पर चल सकता है। ज़करबर्ग ने कहा कि AI नौकरियों को खत्म नहीं करेगा और भविष्यवाणी की कि छोटे व्यवसाय इसके एकीकरण से लाभान्वित होंगे। उन्होंने "सभी के लिए सुपरइंटेलिजेंस" की इच्छा भी व्यक्त की और सुझाव दिया कि AI मौजूदा सहायकों की तुलना में अधिक अंतरंग हो सकता है।', '["Meta CEO Mark Zuckerberg released a manifesto detailing his company''s AI ambitions.", "Meta launched a new open-weight AI model, Muse Glimmer 30B, for developers.", "The new AI model is designed to run on personal computers like Macs and PCs.", "Zuckerberg believes AI will not eliminate jobs and will help small businesses thrive.", "He expressed a goal of achieving \"superintelligence for all\" and developing intimate AI assistants."]'::jsonb, '["मेटा के सीईओ मार्क ज़करबर्ग ने अपनी कंपनी की AI महत्वाकांक्षाओं का विवरण देते हुए एक घोषणापत्र जारी किया।", "मेटा ने डेवलपर्स के लिए एक नया ओपन-वेट AI मॉडल, Muse Glimmer 30B लॉन्च किया।", "नया AI मॉडल मैक और पीसी जैसे व्यक्तिगत कंप्यूटरों पर चलने के लिए डिज़ाइन किया गया है।", "ज़करबर्ग का मानना है कि AI नौकरियों को खत्म नहीं करेगा और छोटे व्यवसायों को फलने-फूलने में मदद करेगा।", "उन्होंने \"सभी के लिए सुपरइंटेलिजेंस\" प्राप्त करने और अंतरंग AI सहायकों को विकसित करने का लक्ष्य व्यक्त किया।"]'::jsonb, 'Science & Tech', 'India', 1, 2, 2, 16, 0, 28, 'center', 40, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 2, "sources": ["Business Standard", "The Free Press Journal"], "owners": ["Business Standard", "The Free Press Journal"]}, "right": {"count": 2, "sources": ["Firstpost", "India Today"], "owners": ["India Today Group", "Network18"]}, "international": {"count": 16, "sources": ["Associated Press", "Bloomberg", "CBC News", "CBS News", "CNBC", "CNN", "Financial Times", "Forbes", "Fortune", "Le Monde", "Los Angeles Times", "NBC News", "The Atlantic", "The Globe and Mail", "The Guardian", "The Washington Post"]}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["Emphasized Meta''s commitment to open-source access for its new AI model."], "center": ["Highlighted the technical capability of the Muse Glimmer 30B model to run on Macs and PCs.", "Focused on Mark Zuckerberg''s prediction that AI will not eliminate jobs and will benefit small businesses."], "right": ["Stressed Mark Zuckerberg''s ambition for \"superintelligence for all\" and Meta''s pursuit of it.", "Framed the release as part of Zuckerberg''s broader manifesto on AI''s future."]}'::jsonb, '{"left": ["अपने नए AI मॉडल के लिए मेटा की ओपन-सोर्स एक्सेस के प्रति प्रतिबद्धता पर जोर दिया।"], "center": ["मैक और पीसी पर चलने वाले Muse Glimmer 30B मॉडल की तकनीकी क्षमता पर प्रकाश डाला।", "मार्क ज़करबर्ग की इस भविष्यवाणी पर ध्यान केंद्रित किया कि AI नौकरियों को खत्म नहीं करेगा और छोटे व्यवसायों को लाभान्वित करेगा।"], "right": ["\"सभी के लिए सुपरइंटेलिजेंस\" के लिए मार्क ज़करबर्ग की महत्वाकांक्षा और मेटा के इसके अनुसरण पर जोर दिया।", "रिलीज को AI के भविष्य पर ज़करबर्ग के व्यापक घोषणापत्र के हिस्से के रूप में प्रस्तुत किया।"]}'::jsonb, '[{"source": "The Washington Post", "owner": "The Washington Post", "lean": "international", "language": "en", "url": "https://news.google.com/rss/articles/CBMiswFBVV95cUxQVXRObzMwdWF5ejg1WUY1WmhHSVhfWFNoM0VMN0xJc0o0SVRiLU1kT1dFdDFtYml4eFhmZEc0WDlDbHZ0X21jcVNoQ19JS0dKNFdTVkczdmFjSThPeW5NRUl6X2ZKMmc2ak9IMWFUVEM0MGFRSUdubmVxdmRPRkNVX1JobjY1VnFLWm5fZ212cVNGOGN3ZXdMQ0NiNDFTSFBWSzlCYWxZdWRaSTl6ekh3ZjB2SQ?oc=5", "headline": "Mark Zuckerberg’s latest manifesto promises to save America with AI"}, {"source": "Le Monde", "owner": "Le Monde", "lean": "international", "language": "en", "url": "https://news.google.com/rss/articles/CBMixwFBVV95cUxPT2ZlYllKOTNmLUNhS0NCMC1jaHJGOWRXUnI4UUJNT21DZnM0RFdWczl4d25QZm5kTjZkMXhqZWNxZFhrT0pFMV9OMzRuSXJMVmdfSDFicy1ySU9rRXRkWmJJdk9WaG14cWJiRV9wZWw2MDdFMXNTaXRDY0ZIVGdiaFZ4eEhTSVpvQ1ZfaFlPN0E2bnVuQVZkTUE5UEc0bUJpbTEyRG0tN2F0Z1BvemdyVDRvOVF6U2tDT2xFLVFvU1RrSmRsQWdr?oc=5", "headline": "Meta CEO Zuckerberg lays out open-source vision for AI"}, {"source": "CBC News", "owner": "CBC News", "lean": "international", "language": "en", "url": "https://news.google.com/rss/articles/CBMib0FVX3lxTFBnUW0waDhzT3NTMWVhOExfOWFUcWdMQm9kenNrMDg4WXJZR0pYSmFmY1cyT3R2WlcyN041YU1iRUliMmpkY2tOWll0Z3ZEeWFGenZIN2dWMWdWZVhzZ1RsV1ZDNTZGNFJjb0hPTzFrWQ?oc=5", "headline": "Meta launches new AI model as Zuckerberg lays out vision for open-weight AI"}, {"source": "NBC News", "owner": "NBC News", "lean": "international", "language": "en", "url": "https://news.google.com/rss/articles/CBMirAFBVV95cUxNR0FCWVBMWXNjZVA0N2ZrOWw5R0JPbk1zSFpwVGs3enBjQ1lTdkpDRm83b0MyeFBydjlXdzdjV0taODQwdHpzUWkwUTNGYnpRZUFfa1IyMlE5WTh0VFQ3YWpLNkxBTkNlbnJuejVaSS11VlNOQWY0cjh5V0N5R0dfWUxMeHpKNlI3ZGtxcGNEZEQ0QTV