INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (12986, 'Spain Faces Migrant Surge at Ceuta Border, Cites Social Media Influence', 'स्पेन के सेउटा बॉर्डर पर प्रवासियों की भीड़, सोशल मीडिया प्रभाव का हवाला', 'Spain has reinforced security at its borders with the Moroccan enclaves of Ceuta and Melilla following a significant influx of migrants. Spanish Defense Minister Margarita Robles stated that responsibility for managing these movements, including those directed via social media, lies with all parties. Reports indicate that groups linked to people-smuggling networks used platforms like Facebook and WhatsApp to attract migrants. The Spanish government plans to return undocumented migrants who arrived in Ceuta in late July to Morocco. The crisis has highlighted challenges for young Moroccans and has led to Spain cancelling leave for soldiers deployed to the area.', 'स्पेन ने प्रवासियों के बड़े पैमाने पर आगमन के बाद मोरक्को के एन्क्लेव सेउटा और मेलिला के साथ अपनी सीमाओं पर सुरक्षा कड़ी कर दी है। स्पेन की रक्षा मंत्री मार्गारीटा रोबल्स ने कहा कि इन आंदोलनों के प्रबंधन की जिम्मेदारी, जिसमें सोशल मीडिया के माध्यम से निर्देशित आंदोलन भी शामिल हैं, सभी पक्षों की है। रिपोर्टों से पता चलता है कि मानव-तस्करी नेटवर्क से जुड़े समूहों ने प्रवासियों को आकर्षित करने के लिए फेसबुक और व्हाट्सएप जैसे प्लेटफार्मों का इस्तेमाल किया। स्पेन सरकार ने जुलाई के अंत में सेउटा में पहुंचे गैर-दस्तावेजी प्रवासियों को मोरक्को वापस भेजने की योजना बनाई है। इस संकट ने युवा मोरक्कोवासियों के लिए चुनौतियों को उजागर किया है और सेउटा सीमा पर तैनात सैनिकों की छुट्टियां रद्द कर दी गई हैं।', '["Spain has increased border security at Ceuta and Melilla due to a large migrant influx.", "Spanish Defense Minister Margarita Robles attributed responsibility for managing migrant movements, including social media direction, to all parties.", "Social media platforms like Facebook and WhatsApp were reportedly used by smuggling networks to attract migrants.", "Spain intends to repatriate undocumented migrants who arrived in Ceuta in late July.", "The migrant surge has led to the cancellation of leave for soldiers deployed to the Ceuta border."]'::jsonb, '["स्पेन ने प्रवासियों की भारी भीड़ के कारण सेउटा और मेलिला में सीमा सुरक्षा बढ़ा दी है।", "स्पेन की रक्षा मंत्री मार्गारीटा रोबल्स ने सभी पक्षों की जिम्मेदारी बताई है, जिसमें सोशल मीडिया द्वारा निर्देशित प्रवासियों के आंदोलन का प्रबंधन भी शामिल है।", "फेसबुक और व्हाट्सएप जैसे सोशल मीडिया प्लेटफॉर्म का इस्तेमाल कथित तौर पर तस्करी नेटवर्क द्वारा प्रवासियों को आकर्षित करने के लिए किया गया था।", "स्पेन जुलाई के अंत में सेउटा पहुंचे गैर-दस्तावेजी प्रवासियों को वापस भेजने का इरादा रखता है।", "प्रवासियों की भीड़ के कारण सेउटा सीमा पर तैनात सैनिकों की छुट्टियां रद्द कर दी गई हैं।"]'::jsonb, 'Crime & Law', 'World', 3, 8, 1, 0, 0, 24, 'center', 67, NULL, NULL, '{"left": {"count": 3, "sources": ["Al Jazeera English", "The Hindu", "The New York Times"], "owners": ["Al Jazeera English", "The Hindu Group", "The New York Times"]}, "center": {"count": 8, "sources": ["Business Insider", "Deutsche Welle", "Euronews", "Financial Times", "Gulf News", "NDTV", "Outlook India", "Telangana Today"], "owners": ["Business Insider", "Deutsche Welle", "Euronews", "Financial Times", "Gulf News", "NDTV", "Outlook India", "Telangana Today"]}, "right": {"count": 1, "sources": ["The Daily Telegraph"], "owners": ["The Daily Telegraph"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["Frames the event as a migrant crisis exacerbated by social media rumors and people-smuggling networks.", "Highlights Spain''s Defense Minister''s statement on shared responsibility for managing migrant movements, including those directed via social media."], "center": ["Emphasizes Spain''s plan to return undocumented migrants to Morocco.", "Notes the use of social media platforms like Facebook and WhatsApp by smuggling networks to attract migrants.", "Mentions the cancellation of leave for soldiers deployed to tackle the crisis."]}'::jsonb, '{"left": ["घटना को सोशल मीडिया की अफवाहों और मानव-तस्करी नेटवर्क से बढ़ी हुई प्रवासी संकट के रूप में प्रस्तुत करता है।", "स्पेन की रक्षा मंत्री के बयान पर प्रकाश डालता है कि सोशल मीडिया द्वारा निर्देशित प्रवासियों के आंदोलनों के प्रबंधन की साझा जिम्मेदारी है।"], "center": ["स्पेन की गैर-दस्तावेजी प्रवासियों को मोरक्को वापस भेजने की योजना पर जोर देता है।", "तस्करी नेटवर्क द्वारा प्रवासियों को आकर्षित करने के लिए फेसबुक और व्हाट्सएप जैसे सोशल मीडिया प्लेटफॉर्म के उपयोग का उल्लेख करता है।", "संकट से निपटने के लिए तैनात सैनिकों की छुट्टियां रद्द करने का उल्लेख करता है।"]}'::jsonb, '[{"source": "Financial Times", "owner": "Financial Times", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMihAFBVV95cUxOWDV5WWptUjBHbnZUZVNkWEc4TG1ydS1rTE1qOFU1cXpkZ2s4dkpRNkdjSUtGM19XZEM0SV9qUHFSU0pXUTRiWjR3VDNlazFza0ZvNHVPR2ZHeHllWmNwZXc2dUg1VTkwLTVialR2OGFTQWZrNjZ1RkFETWhGX3A5blN0OEY?oc=5", "headline": "Spain’s migrant crisis exposes serious challenges for young Moroccans"}, {"source": "The Daily Telegraph", "owner": "The Daily Telegraph", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMiqgFBVV95cUxPSXNvSE13eXptWG1STGNJaHVsZkE2ZEI1TWxxajN0blRmcElKR2pGcHdEZ1RjSjAzRnY5b2ZGeDNMRGNOYVp1WElKUnBQeUx5TFczRFFYbjk4QmtFVFFKUzBVZWpQY25XRzlURVVNUVFXT1NXdDZycE1CRUhTbkhYU2NBSGNLOU9JOTAtTFJUcTlaSlNtQTZmVnlKYUw0cGpNU0ZMaEFrZnBrdw?oc=5", "headline": "Spain cancels all leave for soldiers tackling Ceuta migrant crisis"}, {"source": "Euronews", "owner": "Euronews", "lean": "center", "language": "en", "url": "http://www.euronews.com/my-europe/2