INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (12994, 'Psychiatrist Testifies in Lindsay Clancy Murder Trial', 'लिंडसे क्लैंसी हत्या मामले में मनोचिकित्सक की गवाही', 'Lindsay Clancy is on trial for the first-degree murders of her three young children: Cora, 5; Dawson, 3; and Callan, 8 months. The trial, now in its third week, has featured testimony from psychiatric professionals who treated Clancy. A psychiatrist who treated Clancy testified, with defense attorneys questioning her care. The psychiatrist expressed surprise that Clancy had called a suicide hotline months before the alleged murders. Another psychiatric nurse practitioner also testified, and Clancy reportedly told a caregiver she had "intrusive thoughts" before the killings and expressed concerns about medication dependency.', 'लिंडसे क्लैंसी अपने तीन छोटे बच्चों - 5 वर्षीय कोरा, 3 वर्षीय डॉसन और 8 महीने के कैलैन - की पहली डिग्री हत्याओं के लिए मुकदमे का सामना कर रही हैं। तीसरे सप्ताह में चल रहे मुकदमे में क्लैंसी का इलाज करने वाले मनोरोग पेशेवरों की गवाही शामिल है। क्लैंसी के एक मनोचिकित्सक ने गवाही दी, और बचाव पक्ष के वकीलों ने उनकी देखभाल पर सवाल उठाए। मनोचिकित्सक को इस बात पर आश्चर्य हुआ कि क्लैंसी ने कथित हत्याओं से महीनों पहले आत्महत्या हॉटलाइन पर कॉल किया था। एक अन्य मनोरोग नर्स प्रैक्टिशनर ने भी गवाही दी, और क्लैंसी ने कथित तौर पर एक देखभाल करने वाले को बताया था कि हत्याओं से पहले उनके "बाधित विचार" थे और दवा पर निर्भरता के बारे में चिंता व्यक्त की थी।', '["Lindsay Clancy is on trial for the murders of her three children, Cora, Dawson, and Callan.", "The trial is in its third week and includes testimony from psychiatric professionals.", "Clancy''s psychiatrist testified, and defense attorneys questioned her care.", "The psychiatrist was reportedly surprised Clancy called a suicide hotline prior to the alleged murders.", "Clancy had reportedly told a caregiver about \"intrusive thoughts\" and medication dependency concerns."]'::jsonb, '[]'::jsonb, 'Crime & Law', 'World', 2, 7, 1, 0, 0, 26, 'center', 70, NULL, NULL, '{"left": {"count": 2, "sources": ["CNN", "The Independent"], "owners": ["CNN", "The Independent"]}, "center": {"count": 7, "sources": ["Associated Press", "CBS News", "Forbes", "Hindustan Times", "NBC News", "South China Morning Post", "USA Today"], "owners": ["Associated Press", "CBS News", "Forbes", "HT Media", "NBC News", "South China Morning Post", "USA Today"]}, "right": {"count": 1, "sources": ["Fox News"], "owners": ["Fox News"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Emphasized the testimony of psychiatric professionals involved in Lindsay Clancy''s care.", "Focused on details of Clancy''s mental state, including \"intrusive thoughts\" and medication concerns.", "Highlighted the psychiatrist''s surprise at Clancy calling a suicide hotline prior to the alleged murders."]}'::jsonb, '{"center": ["लिंडसे क्लैंसी की देखभाल में शामिल मनोरोग पेशेवरों की गवाही पर जोर दिया।", "क्लैंसी की मानसिक स्थिति के विवरण पर ध्यान केंद्रित किया, जिसमें \"बाधित विचार\" और दवा संबंधी चिंताएं शामिल थीं।", "कथित हत्याओं से पहले लिंडसे क्लैंसी द्वारा आत्महत्या हॉटलाइन पर कॉल करने पर मनोचिकित्सक के आश्चर्य पर प्रकाश डाला।"]}'::jsonb, '[{"source": "CNN", "owner": "CNN", "lean": "left", "language": "en", "url": "https://news.google.com/rss/articles/CBMiggFBVV95cUxOckdhSmFxTlNQNGExTnNELVZxYU9BM0poTVBoZFQydDNxbUhTVzZYeTJ2d1BqMmt0X1pReDNRdXVTRzFVWFZVbkJLeTJ5d3pfSGNHMUdQM19NUDFBcG1yZ2dxMjlWMEl1c0l5U3JMZ2N5WkI3a3F3SWVENy1FR0pieTVn?oc=5", "headline": "Defense for Lindsay Clancy questions psychiatrist who treated her"}, {"so