INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13149, 'The Office Actor Lucy Davis Reveals Incurable Stage 4 Breast Cancer Diagnosis', 'द ऑफिस की अभिनेत्री लुसी डेविस ने लाइलाज स्टेज 4 स्तन कैंसर का खुलासा किया', 'Lucy Davis, an actor known for her role in the UK version of "The Office," has announced she has incurable stage 4 breast cancer. The 53-year-old stated that the cancer has spread to her bones and that it is too late for chemotherapy. Davis revealed she was diagnosed a year and a half ago. The news has led to messages of support from other stars.', 'लुसी डेविस, जो "द ऑफिस" के यूके संस्करण में अपनी भूमिका के लिए जानी जाती हैं, ने घोषणा की है कि उन्हें लाइलाज स्टेज 4 स्तन कैंसर है। 53 वर्षीय अभिनेत्री ने बताया कि कैंसर उनकी हड्डियों तक फैल चुका है और कीमोथेरेपी के लिए बहुत देर हो चुकी है। डेविस ने खुलासा किया कि उन्हें डेढ़ साल पहले इसका पता चला था। इस खबर के बाद अन्य सितारों ने समर्थन संदेश साझा किए हैं।', '["Actor Lucy Davis announced she has stage 4 breast cancer.", "The cancer is incurable and has spread to her bones.", "Davis stated it is too late for chemotherapy treatment.", "She received the diagnosis approximately 18 months ago.", "Other celebrities have shared messages of support for Davis."]'::jsonb, '["अभिनेत्री लुसी डेविस ने घोषणा की है कि उन्हें स्टेज 4 स्तन कैंसर है।", "कैंसर लाइलाज है और उनकी हड्डियों तक फैल चुका है।", "डेविस ने कहा कि कीमोथेरेपी के लिए बहुत देर हो चुकी है।", "उन्हें लगभग 18 महीने पहले निदान हुआ था।", "अन्य हस्तियों ने डेविस के लिए समर्थन संदेश साझा किए हैं।"]'::jsonb, 'Society', 'World', 5, 12, 4, 0, 0, 36, 'center', 57, NULL, NULL, '{"left": {"count": 5, "sources": ["Daily Mirror", "Los Angeles Times", "The Guardian", "The Independent", "The Washington Post"], "owners": ["Daily Mirror", "Los Angeles Times", "The Guardian", "The Independent", "The Washington Post"]}, "center": {"count": 12, "sources": ["ABC Australia", "BBC News", "Euronews", "Evening Standard", "Gulf News", "Irish Independent", "Mathrubhumi English", "Metro (UK)", "NBC News", "The Age", "The Statesman", "The Sydney Morning Herald"], "owners": ["ABC Australia", "BBC News", "Euronews", "Evening Standard", "Gulf News", "Irish Independent", "Mathrubhumi English", "Metro (UK)", "NBC News", "The Age", "The Statesman", "The Sydney Morning Herald"]}, "right": {"count": 4, "sources": ["Daily Mail", "Fox News", "The Daily Telegraph", "Times Now"], "owners": ["Daily Mail", "Fox News", "The Daily Telegraph", "Times Now"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["The two centrist outlets focused on the actor''s diagnosis, emphasizing the incurable nature of the cancer and the statement that it was too late for chemotherapy.", "These outlets highlighted the actor''s age and the timeline of her diagnosis."], "right": ["The sole right-leaning outlet emphasized that the cancer has spread to the actor''s bones and is incurable."]}'::jsonb, '{"center": ["दोनों मध्यमार्गी आउटलेट्स ने अभिनेत्री के निदान पर ध्यान केंद्रित किया, कैंसर की लाइलाज प्रकृति और कीमोथेरेपी के लिए बहुत देर हो जाने के बयान पर जोर दिया।", "इन आउटलेट्स ने अभिनेत्री की उम्र और उनके निदान की समय-सीमा पर प्रकाश डाला।"], "right": ["एकमात्र दक्षिणपंथी आउटलेट ने इस बात पर जोर दिया कि कैंसर अभिनेत्री की हड्डियों तक फैल चुका है और यह लाइलाज है।"]}'::jsonb, '[{"source": "The Guardian", "owner": "The Guardian", "lean": "left", "language": "en", "url": "https://www.theguardian.com/tv-and-radio/2026/aug/11/lucy-davis-the-office-actor-stage-four-breast-cancer", "headline": "The Office actor Lucy Davis says she has incurable stage four breast cancer"}, {"source": "The Daily Telegraph", "owner": "The Daily Telegraph", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMiogFBVV95cUxNVm9VLWRHN1RraE1lTHlycWlIdlc2UERVcDZnTTI3Tkd4dzhUQTVpVWRxZmk2a2M4Sm9pRjAwZ1liVDdqel9PUUJBSjY1U1M3NnhXcEVIWkF0dXpjekoxZDdTYWVkS19wU19KM0g3V21ZaTJiMEZjQk5Vbmdrdmx3aUJ1NXlmZUNQUXRMdXhmdDRpdnNscklHNEdONGlld2d5TFE?oc=5", "headline": "The Office actress Lucy Davis diagnosed with incurable breast cancer"}, {"source": "Metro (UK)", "owner": "Metro (UK)", "lean": "center", "language": "en", "url": "https://metro.co.uk/2026/08/11/eastenders-casts-major-tv-star-tragic-denise-cancer-story-29353187", "headline": "EastEnders casts major TV star for tragic Denise cancer story"}, {"source": "Daily Mail", "owner": "Daily Mail", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMiyAFBVV95cUxNZ2lNUGZJUzA0SlZCQmRNUlVQNkJtcVhBcGJEelpTUTdYdnpZZ0w2eFFLRkRMMUd1MzlMNTRkSnBpTGFTSXNOODNHVVNTOGx3Y1J0bEpxUDRzOVBXdUljckJSRzZQMDhJUkx0dldyQmhSMC14R1ZqT09kY1luWGFCbTBzdm5hdUpiLXVUa3lyd05YbXNMNEV1LV9EUUNQbXVHZ0p5NkIzdnM4dVFfNVhrLWZrNGtVZXRtbW9XV01DTU9fSlFKVzVBbw?oc=5", "headline": "Stars share messages of support for Lucy Davis after cancer diagnosis"}, {"source": "ABC Australia", "owner": "ABC Australia", "lean": "center", "language": "en", "url": "https://www.abc.net.au/news/2026-08-12/the-office-lucy-davis-breast-cancer/107026596", "headline": "The Office star Lucy Davis announces she has incurable cancer"}, {"source": "Daily Mirror", "owner": "Daily Mirror", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "The Office star Lucy Davis reveals she''s been diagnosed with incurable breast cancer aged 53"}, {"source": "ABC Australia", "owner": "ABC Australia", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMijAFBVV95cUxPZWVqZXF0N1F1eUZYWVJjVEJFTHBxRE5uaFVPRVp0ZUstekVGRjAtRDJLb2VwOWFDSXpfUVpQNVZiSzl1TEttNGtPQ01yN2hSZ3JRX1B2LVFj