er, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, content_complete = EXCLUDED.content_complete, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13389, 'New Zealand PM Luxon Survives Party Leadership Vote Amidst Election Speculation', 'न्यूजीलैंड के पीएम लक्सन चुनाव पूर्व नेतृत्व वोट में बचे', 'New Zealand Prime Minister Christopher Luxon survived a vote of confidence within his own party. The vote followed speculation about his leadership, occurring approximately 12 weeks before a general election. Luxon stated he has the full support of his party and that they are united and determined to win the election. The challenge exposed divisions within the party ahead of the upcoming polls.', 'न्यूजीलैंड के प्रधानमंत्री क्रिस्टोफर लक्सन ने अपनी पार्टी के भीतर विश्वास मत हासिल कर लिया। यह मत नेतृत्व को लेकर चल रही अटकलों के बाद हुआ, जो आम चुनाव से लगभग 12 सप्ताह पहले हुआ। लक्सन ने कहा कि उन्हें अपनी पार्टी का पूरा समर्थन प्राप्त है और वे एकजुट हैं और चुनाव जीतने के लिए दृढ़ संकल्पित हैं। इस चुनौती ने आगामी चुनावों से पहले पार्टी के भीतर दरारें उजागर कीं।', '["New Zealand Prime Minister Christopher Luxon faced and survived a vote of confidence from his party.", "The vote occurred amidst ongoing speculation regarding Luxon''s leadership.", "The challenge to his leadership took place about 12 weeks before a general election.", "Luxon asserted that his party is united and has his full support.", "The leadership challenge highlighted cracks within the party before the election."]'::jsonb, '["न्यूजीलैंड के प्रधानमंत्री क्रिस्टोफर लक्सन ने अपनी पार्टी से विश्वास मत का सामना किया और उसमें बचे रहे।", "यह मत लक्सन के नेतृत्व को लेकर चल रही अटकलों के बीच हुआ।", "नेतृत्व की यह चुनौती आम चुनाव से लगभग 12 सप्ताह पहले हुई।", "लक्सन ने दावा किया कि उनकी पार्टी एकजुट है और उन्हें पूरा समर्थन प्राप्त है।", "नेतृत्व की चुनौती ने चुनाव से पहले पार्टी के भीतर दरारें उजागर कीं।"]'::jsonb, 'Politics', 'World', 1, 6, 1, 0, 0, 11, 'center', 75, NULL, NULL, '{"left": {"count": 1, "sources": ["The Independent"], "owners": ["The Independent"]}, "center": {"count": 6, "sources": ["ABC Australia", "Associated Press", "BBC News", "Channel News Asia", "Reuters", "The Print"], "owners": ["ABC Australia", "Associated Press", "BBC News", "Channel News Asia", "Reuters", "The Print"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["The sole centrist outlet emphasized that Prime Minister Luxon survived a confidence vote, framing it around leadership speculation.", "This coverage highlighted the timing of the vote just weeks before a general election."], "right": ["The sole right-leaning outlet reported that Luxon survived the leadership vote months before the NZ election."]}'::jsonb, '{"center": ["एकमात्र वाम-झुकाव वाले आउटलेट ने इस बात पर जोर दिया कि प्रधानमंत्री लक्सन ने विश्वास मत हासिल कर लिया, इसे नेतृत्व की अटकलों के इर्द-गिर्द प्रस्तुत किया।", "इस कवरेज में आम चुनाव से कुछ हफ्ते पहले ही वोटिंग के समय पर प्रकाश डाला गया।"], "right": ["एकमात्र दक्षिणपंथी आउटलेट ने रिपोर्ट किया कि लक्सन ने न्यूजीलैंड चुनाव से महीनों पहले नेतृत्व वोट में जीत हासिल की।"]}'::jsonb, '[{"source": "Reuters", "owner": "Reuters", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMixwFBVV95cUxOZmt2UzVWOW5uQVlLYTVib0dhT0ljWnBzaVFERTlnTWI3bUhxR291RHBRclZwRnNnVFRJcHNBSlNrNVpaZElvVUxZWWVpOVN2WjFvdjFjSnlSMzlmWU0ydmlacF9pUzh6VU5wN3BBN0ZYRXBCSW5lQXptdjVCY2V5b0stcFg1dzRMUzNwM2tyZzhFQ1VDUVlTdVBtS3VEdmRaX192amJab2lSOTNOMTFCTGFoRldmZmNYYkREbjY5X2VWWktrUG1Z?oc=5", "headline": "New Zealand''s Luxon calls meeting of lawmakers to address leadership specul