GZ1ZlBrUkM4UmFGTWE0WjNHSkV4SUZMQXVLbEs1Y0NFaVdSX0t3T3pKR1VOTVgycEZWSXQyYWZTRlJ2elUzN182aE96UFUxVmZHYTFFRUdwZnlVR0ZHeENuUDdyR09icw?oc=5", "headline": "Luxon survives leadership vote months before NZ election"}, {"source": "The Independent", "owner": "The Independent", "lean": "left", "language": "en", "url": "https://www.independent.co.uk/news/world/australasia/new-zealand-christopher-luxon-national-party-caucus-meeting-b3031630.html", "headline": "New Zealand PM survives second challenge to leadership just weeks before general election"}, {"source": "BBC News", "owner": "BBC News", "lean": "center", "language": "en", "url": "https://www.bbc.com/news/articles/cx2ve2jk5qeo", "headline": "New Zealand PM survives second leadership challenge ahead of election"}, {"source": "The Print", "owner": "The Print", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "New Zealand’s Luxon survives confidence vote after more leadership speculation"}, {"source": "Associated Press", "owner": "Associated Press", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "New Zealand Prime Minister Luxon says he survived a leadership vote in his own party"}], "coverage": {"left": {"count": 1, "sources": ["The Independent"], "owners": ["The Independent"]}, "center": {"count": 6, "sources": ["ABC Australia", "Associated Press", "BBC News", "Channel News Asia", "Reuters", "The Print"], "owners": ["ABC Australia", "Associated Press", "BBC News", "Channel News Asia", "Reuters", "The Print"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 8, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://live-production.wcms.abc-cdn.net.au/7941460d2c52fa305a618c10d5d38e9e?impolicy=wcms_crop_resize&cropH=1152&cropW=2048&xPos=0&yPos=146&width=862&height=485', FALSE, FALSE, 'llm', NULL, NULL, NULL, '2026-08-13T05:52:50.195172'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, content_complete = EXCLUDED.content_complete, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13392, 'Nationwide ''Har Ghar Tiranga'' Campaign Celebrates National Flag', 'राष्ट्रव्यापी ''हर घर तिरंगा'' अभियान राष्ट्रीय ध्वज का उत्सव मनाता है', 'Across India, a ''Har Ghar Tiranga'' campaign encouraged citizens to display the national flag. Prime Minister Modi called on every household to participate. Numerous rallies, including bike rallies and ''Tiranga Yatras'', were held in various locations such as Delhi, Kashmir, Bastar, and Indore. Officials, including Uttar Pradesh Chief Minister Adityanath and Jammu and Kashmir Lieutenant Governor Manoj Sinha, highlighted the campaign''s significance as a tribute to freedom fighters'' sacrifices and a symbol of national pride and unity. The campaign also saw participation from Union Ministers and Vice-President Radhakrishnan.', 'पूरे भारत में, ''हर घर तिरंगा'' अभियान ने नागरिकों को राष्ट्रीय ध्वज प्रदर्शित करने के लिए प्रोत्साहित किया। प्रधानमंत्री मोदी ने हर घर से भाग लेने का आह्वान किया। दिल्ली, कश्मीर, बस्तर और इंदौर जैसे विभिन्न स्थानों पर बाइक रैलियों और ''तिरंगा यात्राओं'' सहित कई रैलियाँ आयोजित की गईं। उत्तर प्रदेश के मुख्यमंत्री आदित्यनाथ और जम्मू और कश्मीर के उपराज्यपाल मनोज सिन्हा सहित अधिकारियों ने स्वतंत्रता सेनानियों के बलिदान के प्रति श्रद्धांजलि और राष्ट्रीय गौरव और एकता के प्रतीक के रूप में अभियान के महत्व पर प्रकाश डाला। अभियान में केंद्रीय मंत्रियों और उपराष्ट्रपति राधाकृष्णन ने भी भाग लिया।', '["The ''Har Ghar Tiranga'' campaign urged citizens to display the national flag at their homes.", "Prime Minister Modi called on every household to participate in the campaign.", "Numerous rallies and ''Tiranga Yatras'' were organized across different regions, including Delhi, Kashmir, Bastar, and Indore.", "Officials framed the campaign as a tribute to freedom fighters and a symbol of national pride and unity.", "Vice-President Radhakrishnan and Union Ministers participated in related events."]'::jsonb, '["''हर घर तिरंगा'' अभियान ने नागरिकों से अपने घरों में राष्ट्रीय ध्वज प्रदर्शित करने का आग्रह किया।", "प्रधानमंत्री मोदी ने हर घर से अभियान में भाग लेने का आह्वान किया।", "दिल्ली, कश्मीर, बस्तर और इंदौर सहित विभिन्न क्षेत्रों में कई रैलियाँ और ''तिरंगा यात्राएँ'' आयोजित की गईं।", "अधिकारियों ने अभियान को स्वतंत्रता सेनानियों के प्रति श्रद्धांजलि और राष्ट्रीय गौरव और एकता के प्रतीक के रूप में प्रस्तुत किया।", "उपराष्ट्रपति राधाकृष्णन और केंद्रीय मंत्रियों ने संबंधित कार्यक्रमों में भाग लिया।"]'::jsonb, 'Society', 'India', 1, 9, 1, 0, 0, 29, 'center', 82, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 9, "sources": ["Deccan Chronicle", "Deccan Herald", "Greater Kashmir", "Outlook India", "Telangana Today", "The Economic Times", "The Free Press Journal", "The Statesman", "The Times of India", "The Tribune"], "owners": ["Deccan Chronicle", "Deccan Herald", "Greater Kashmir", "Outlook India", "Telangana Today", "The Free Press Journal", "The Statesman", "The Tribune", "Times Group"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["Emphasized Uttar Pradesh Chief Minister Adityanath''s statement that the campaign is a tribute to freedom fighters'' sacrifices."], "center": ["Highlighted Prime Minister Modi''s call for participation and the involvement of NDA MPs in a Delhi rally.", "Featured Vice-President Radhakrishnan flagging off a Tiranga bike rally in Delhi.", "Included statements from Jammu and Kashmir Lieutenant Governor Manoj Sinha about the Tiranga Yatra sending a clear message and the campaign''s importance.", "Reported on various local events, such as a vehicle rally and rural yatras in Indore and a campaign at AIIMS Bibinagar."], "right": ["Focused on Tiranga rallies held in Kashmir and cited LG Sinha''s statement that the Tricolour is flying high as India''s living conscience.", "Reported on the Bastar Tiranga Yatra signaling a new era of peace and development."]}'::jsonb, '{"left": ["उत्तर प्रदेश के मुख्यमंत्री आदित्यनाथ के इस बयान पर जोर दिया कि यह अभियान स्वतंत्रता सेनानियों के बलिदानों के प्रति श्रद्धांजलि है।"], "center": ["प्रधानमंत्री मोदी के भागीदारी के आह्वान और दिल्ली में एक रैली में एनडीए सांसदों की भागीदारी पर प्रकाश डाला।", "उपराष्ट्रपति राधाकृष्णन द्वारा दिल्ली में तिरंगा बाइक रैली को हरी झंडी दिखाने की खबर दी।", "जम्मू और कश्मीर के उपराज्यपाल मनोज सिन्हा के बयानों को शामिल किया, जिसमें तिरंगा यात्रा एक स्पष्ट संदेश भेज रही है और अभियान के महत्व पर जोर दिया गया।", "इंदौर में एक वाहन रैली और ग्रामीण यात्राओं और एआईआईएमएस बिबीनगर में एक अभियान जैसी विभिन्न स्थानीय घटनाओं की सूचना दी।"], "right": ["कश्मीर में आयोजित तिरंगा रैलियों पर ध्यान केंद्रित किया और एलजी सिन्हा के इस बयान का हवाला दिया कि तिरंगा भारत के जीवित विवेक के रूप में ऊंचा लहरा रहा है।", "शांति और विकास के एक नए युग का संकेत देने वाली बस्तर तिरंगा यात्रा की सूचना दी।"]}'::jsonb, '[{"source": "Deccan Herald", "owner": "Deccan Herald", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMixAFBVV95cUxQOVBjbUpiUE9LRU9rSXNmeDJDbU9MSDM1WGxfRW9nMnQ3REF5RGpYSURFenRsa043WWtuSm41ZEhVNUNKR1EtQllBM3hMTEZKMmVxODRsbll2NWhhLU9RZTlyUlRwZFRFczR6elItSFJUeFo3UkRaMjM2STUzb1Vnbkx2Wm1IQmtVQ2dsQzZsVGR4QTY3Sld1ajBqc001ZS05NFJYWEROSFpzZzNkLVcxSTAta044QWY5MFZVR011S1pKTnBJ?oc=5", "headline": "WATCH: PM Modi calls for ''Har Ghar Tiranga'', NDA MPs to join rally in Delhi"}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Vande Mataram Echoes Across AIIMS Bibinagar During Har Ghar Tiranga Campaign"}, {"source": "The Times of India", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://timesofindia.indiatimes.com/india/celebrate-har-ghar-tiranga-drive-pm-modi-calls-on-every-household/articleshow/133167109.cms", "headline": "Celebrate ‘Har Ghar Tiranga’ drive, PM Modi calls on every household"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/news/national/uttar-pradesh/har-ghar-tiranga-campaign-tribute-to-freedom-fighters-sacrifices-cm-adityanath/article71327352.ece", "headline": "''Har Ghar Tiranga'' campaign tribute to freedom fighters'' sacrifices: CM Adityanath"}, {"source": "The Times of India", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://timesofindia.indiatimes.com/india/bharat-is-one-and-will-be-forever-vp-radhakrishnan-flags-off-tiranga-bike-rally-in-delhi-nda-mps-participate/articleshow/133170115.cms", "headline": "‘Bharat is one, and will be forever’: VP Radhakrishnan flags off Tiranga bike rally in Delhi, NDA MPs participate"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Cycling is a message of fitness: Union Sports Minister Mansukh Mandaviya at Har Ghar Tiranga rally"}, {"source": "Telangana Today", "owner": "Telangana Today", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMipAFBVV95cUxQMm5MNDBRWXpnQUxWRC1JaEgwdEMzLTFXSDhVc1NaX3d6LVhoUjI3Wk5wOU1EU1NpYWFqZFNFQkZIWDhYT0ZXOGRWSVFudGFvN2c0SENMWlUwc0tCUVBFM1RaRXNYMFhvTmw1cmtJTVdlbldDZ1FiN0hrNlMzZDFaRHJSRTNFeHJTc1pDVFdSMkNGNzkyODFhU096bU11bjRRQm8wNA?oc=5", "headline": "Vice-President Radhakrishnan flags off Har Ghar Tiranga bike rally in Delhi"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Indore’s Har Ghar Tiranga Campaign Sees Grand Vehicle Rally, Rural Yatras"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Har Ghar Tiranga must remain high in our thoughts, character, actions: LG Sinha"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Har Ghar Tiranga must remain high in thoughts, character, actions: LG Sinha"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "LG Manoj Sinha leads “Tiranga Rally” from SKICC to Botanical Garden Srinagar"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Thousands join mega Tiranga Rally in Anantnag ahead of Independence Day"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMipwFBVV95cUxPcDB5TEVBd3FVbU5nMU1PLXFoWkduNVVyNTl0QjBzZVVUbE50SF9tY2stWHlQS29BcC05a1h5U2RDcWJaVFdFODgxZGtXMDBTMXRVRldPZWgzSk1ybkl3d2RsQ0w0aVRyRW9JN3VXVWdtZ1BLMHpRanNFVFhaUWxUb2JUMmFfdFJUM1FwSVA5Uk1lMk42QnN2SDFVY3pROVFQMUJ5aS1FSQ?oc=5", "headline": "Tiranga rallies held across Kashmir; L-G says Tricolour flying high as India''s living conscience"}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Chhattisgarh: 3-Day ''Bastar Tiranga Yatra'' Begins from Ex-Maoist Hub Abujhmad"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "ATV riders, locals join Tiranga rally from Tangmarg to Drung"}, {"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "What We Know About BJP''s Tiranga Yatras Ahead Of Independence Day"}, {"source": "The Statesman", "owner": "The Statesman", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Har Ghar Tiranga: Surya Sen Mahavidyalaya organised a Cycle Rally and Walkathon in Siliguri"}, {"source": "The Statesman", "owner": "The Statesman", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Grand Tiranga Yatras Held Across Four Delhi Districts Ahead of 80th Independence Day"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://www.tribuneindia.com/news/jalandhar/tiranga-yatras-held-across-13-bjp-mandals-in-jalandhar", "headline": "Tiranga Yatras held across 13 BJP mandals in Jalandhar"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/news/national/jammu-and-kashmir/hundreds-attended-tiranga-yatra-in-kashmir-lg-says-sends-a-clear-message/article71336664.ece", "headline": "Hundreds attended Tiranga Yatra in Kashmir; LG says ‘sends a clear message’"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMirgFBVV95cUxQTUxLSzkxb3B3RHFQbnVFcEpmZ0RTSGw5UG14ekJkZzBwbTFTN1VPRVB0dHc1ZlhPTzJpaHdOM05WTHRMM3JEaFBXVFlpbkpwQjhhdi11ZGc2QldaZG14UmJRY1puSlQ0YVY4dmRhR1VIcTluZlpQQm1CTkpHMzRLZVRZVUZ5M1lIMENVOWQ2M0FMUG4tcW1QSXA1ZW5SNXZfbENHT3dMNjlxSGhNNXc?oc=5", "headline": "Bastar Tiranga Yatra Begins, Signals New Era of Peace and Development"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Tricolour is soul of our nation: LG Sinha"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MP Ramzan attends INDIA Alliance meeting in New Delhi"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://www.tribuneindia.com/news/delhi/delhi-cm-rekha-bjp-national-president-nabin-lead-tiranga-yatra", "headline": "Delhi CM Rekha , BJP national president Nabin lead Tiranga Yatra"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "NDA MPs hold ‘Mangal Milan’ meeting ahead of Independence Day"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Security checks, frisking intensified across north Kashmir ahead of Independence Day"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/news/newsblogs/independence-day-parliament-pm-modi-amit-shah-rahul-gandhi-iran-us-war-russia-ukraine-war-trump-tariffs-trade-deal-india-us/liveblog/133195978.cms", "headline": "Breaking News Live Updates : Delhi wakes up to heightened security ahead of 79th Independence Day celebrations"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Security beefed up in Srinagar ahead of Independence Day celebrations"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Independence Day Celebration | Police, security agencies directed to ensure foolproof security arrangements in Jammu"}]'::jsonb, '{"title": "Nationwide ''Har Ghar Tiranga'' Campaign Celebrates National Flag", "summary": "Across India, a ''Har Ghar Tiranga'' campaign encouraged citizens to display the national flag. Prime Minister Modi called on every household to participate. Numerous rallies, including bike rallies and ''Tiranga Yatras'', were held in various locations such as Delhi, Kashmir, Bastar, and Indore. Officials, including Uttar Pradesh Chief Minister Adityanath and Jammu and Kashmir Lieutenant Governor Manoj Sinha, highlighted the campaign''s significance as a tribute to freedom fighters'' sacrifices and a symbol of national pride and unity. The campaign also saw participation from Union Ministers and Vice-President Radhakrishnan.", "summary_points": ["The ''Har Ghar Tiranga'' campaign urged citizens to display the national flag at their homes.", "Prime Minister Modi called on every household to participate in the campaign.", "Numerous rallies and ''Tiranga Yatras'' were organized across different regions, including Delhi, Kashmir, Bastar, and Indore.", "Officials framed the campaign as a tribute to freedom fighters and a symbol of national pride and unity.", "Vice-President Radhakrishnan and Union Ministers participated in related events."], "title_hi": "राष्ट्रव्यापी ''हर घर तिरंगा'' अभियान राष्ट्रीय ध्वज का उत्सव मनाता है", "summary_hi": "पूरे भारत में, ''हर घर तिरंगा'' अभियान ने नागरिकों को राष्ट्रीय ध्वज प्रदर्शित करने के लिए प्रोत्साहित किया। प्रधानमंत्री मोदी ने हर घर से भाग लेने का आह्वान किया। दिल्ली, कश्मीर, बस्तर और इंदौर जैसे विभिन्न स्थानों पर बाइक रैलियों और ''तिरंगा यात्राओं'' सहित कई रैलियाँ आयोजित की गईं। उत्तर प्रदेश के मुख्यमंत्री आदित्यनाथ और जम्मू और कश्मीर के उपराज्यपाल मनोज सिन्हा सहित अधिकारियों ने स्वतंत्रता सेनानियों के बलिदान के प्रति श्रद्धांजलि और राष्ट्रीय गौरव और एकता के प्रतीक के रूप में अभियान के महत्व पर प्रकाश डाला। अभियान में केंद्रीय मंत्रियों और उपराष्ट्रपति राधाकृष्णन ने भी भाग लिया।", "summary_points_hi": ["''हर घर तिरंगा'' अभियान ने नागरिकों से अपने घरों में राष्ट्रीय ध्वज प्रदर्शित करने का आग्रह किया।", "प्रधानमंत्री मोदी ने हर घर से अभियान में भाग लेने का आह्वान किया।", "दिल्ली, कश्मीर, बस्तर और इंदौर सहित विभिन्न क्षेत्रों में कई रैलियाँ और ''तिरंगा यात्राएँ'' आयोजित की गईं।", "अधिकारियों ने अभियान को स्वतंत्रता सेनानियों के प्रति श्रद्धांजलि और राष्ट्रीय गौरव और एकता के प्रतीक के रूप में प्रस्तुत किया।", "उपराष्ट्रपति राधाकृष्णन और केंद्रीय मंत्रियों ने संबंधित कार्यक्रमों में भाग लिया।"], "framing": {"left": ["Emphasized Uttar Pradesh Chief Minister Adityanath''s statement that the campaign is a tribute to freedom fighters'' sacrifices."], "center": ["Highlighted Prime Minister Modi''s call for participation and the involvement of NDA MPs in a Delhi rally.", "Featured Vice-President Radhakrishnan flagging off a Tiranga bike rally in Delhi.", "Included statements from Jammu and Kashmir Lieutenant Governor Manoj Sinha about the Tiranga Yatra sending a clear message and the campaign''s importance.", "Reported on various local events, such as a vehicle rally and rural yatras in Indore and a campaign at AIIMS Bibinagar."], "right": ["Focused on Tiranga rallies held in Kashmir and cited LG Sinha''s statement that the Tricolour is flying high as India''s living conscience.", "Reported on the Bastar Tiranga Yatra signaling a new era of peace and development."]}, "framing_hi": {"left": ["उत्तर प्रदेश के मुख्यमंत्री आदित्यनाथ के इस बयान पर जोर दिया कि यह अभियान स्वतंत्रता सेनानियों के बलिदानों के प्रति श्रद्धांजलि है।"], "center": ["प्रधानमंत्री मोदी के भागीदारी के आह्वान और दिल्ली में एक रैली में एनडीए सांसदों की भागीदारी पर प्रकाश डाला।", "उपराष्ट्रपति राधाकृष्णन द्वारा दिल्ली में तिरंगा बाइक रैली को हरी झंडी दिखाने की खबर दी।", "जम्मू और कश्मीर के उपराज्यपाल मनोज सिन्हा के बयानों को शामिल किया, जिसमें तिरंगा यात्रा एक स्पष्ट संदेश भेज रही है और अभियान के महत्व पर जोर दिया गया।", "इंदौर में एक वाहन रैली और ग्रामीण यात्राओं और एआईआईएमएस बिबीनगर में एक अभियान जैसी विभिन्न स्थानीय घटनाओं की सूचना दी।"], "right": ["कश्मीर में आयोजित तिरंगा रैलियों पर ध्यान केंद्रित किया और एलजी सिन्हा के इस बयान का हवाला दिया कि तिरंगा भारत के जीवित विवेक के रूप में ऊंचा लहरा रहा है।", "शांति और विकास के एक नए युग का संकेत देने वाली बस्तर तिरंगा यात्रा की सूचना दी।"]}, "topic": "Society", "region": "India", "published_at": null, "image_url": "https://static.to