gle.com/rss/articles/CBMirgFBVV95cUxQTUxLSzkxb3B3RHFQbnVFcEpmZ0RTSGw5UG14ekJkZzBwbTFTN1VPRVB0dHc1ZlhPTzJpaHdOM05WTHRMM3JEaFBXVFlpbkpwQjhhdi11ZGc2QldaZG14UmJRY1puSlQ0YVY4dmRhR1VIcTluZlpQQm1CTkpHMzRLZVRZVUZ5M1lIMENVOWQ2M0FMUG4tcW1QSXA1ZW5SNXZfbENHT3dMNjlxSGhNNXc?oc=5", "headline": "Bastar Tiranga Yatra Begins, Signals New Era of Peace and Development"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Tricolour is soul of our nation: LG Sinha"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MP Ramzan attends INDIA Alliance meeting in New Delhi"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://www.tribuneindia.com/news/delhi/delhi-cm-rekha-bjp-national-president-nabin-lead-tiranga-yatra", "headline": "Delhi CM Rekha , BJP national president Nabin lead Tiranga Yatra"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "NDA MPs hold ‘Mangal Milan’ meeting ahead of Independence Day"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Security checks, frisking intensified across north Kashmir ahead of Independence Day"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/news/newsblogs/independence-day-parliament-pm-modi-amit-shah-rahul-gandhi-iran-us-war-russia-ukraine-war-trump-tariffs-trade-deal-india-us/liveblog/133195978.cms", "headline": "Breaking News Live Updates : Delhi wakes up to heightened security ahead of 79th Independence Day celebrations"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Security beefed up in Srinagar ahead of Independence Day celebrations"}, {"source": "Greater Kashmir", "owner": "Greater Kashmir", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Independence Day Celebration | Police, security agencies directed to ensure foolproof security arrangements in Jammu"}], "coverage": {"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 9, "sources": ["Deccan Chronicle", "Deccan Herald", "Greater Kashmir", "Outlook India", "Telangana Today", "The Economic Times", "The Free Press Journal", "The Statesman", "The Times of India", "The Tribune"], "owners": ["Deccan Chronicle", "Deccan Herald", "Greater Kashmir", "Outlook India", "Telangana Today", "The Free Press Journal", "The Statesman", "The Tribune", "Times Group"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 12, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://static.toiimg.com/photo/msid-133167113,imgsize-157298.cms', FALSE, FALSE, 'llm', NULL, NULL, NULL, '2026-08-13T06:50:20.105012'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, content_complete = EXCLUDED.content_complete, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13417, 'Pentagon report: US strikes killed 153 civilians in Yemen in 2025', 'पेंटागन रिपोर्ट: 2025 में अमेरिकी हमलों में 153 नागरिक मारे गए', 'A Pentagon assessment released in 2025 states that U.S. military operations killed 153 civilians and wounded 243. The report specifically details U.S. strikes targeting Houthis in Yemen. This assessment follows the dismantling of an office focused on mitigating unintended casualties. The Pentagon review covered three specific attacks, with 15 additional incidents still under review.', '2025 में जारी एक पेंटागन मूल्यांकन में कहा गया है कि अमेरिकी सैन्य अभियानों में 153 नागरिक मारे गए और 243 घायल हुए। रिपोर्ट में विशेष रूप से यमन में हौथियों को लक्षित करने वाले अमेरिकी हमलों का विवरण दिया गया है। यह मूल्यांकन अनपेक्षित हताहतों को कम करने पर केंद्रित एक कार्यालय को भंग करने के बाद आया है। पेंटागन समीक्षा में तीन विशिष्ट हमलों को शामिल किया गया था, जबकि 15 अतिरिक्त घटनाओं की अभी भी समीक्षा की जा रही है।', '["A Pentagon assessment found U.S. military operations killed 153 civilians in 2025.", "The same assessment reported 243 civilians were wounded.", "The strikes specifically targeted Houthis in Yemen.", "The report was released following the dismantling of an office focused on mitigating civilian casualties.", "The review covered three specific attacks, with 15 more incidents pending review."]'::jsonb, '["एक पेंटागन मूल्यांकन में पाया गया कि 2025 में अमेरिकी सैन्य अभियानों में 153 नागरिक मारे गए।", "इसी मूल्यांकन में 243 नागरिकों के घायल होने की सूचना दी गई।", "हमलों में विशेष रूप से यमन में हौथियों को निशाना बनाया गया था।", "यह रिपोर्ट नागरिक हताहतों को कम करने पर केंद्रित एक कार्यालय को भंग करने के बाद जारी की गई थी।", "समीक्षा में तीन विशिष्ट हमलों को शामिल किया गया था, जिसमें 15 और घटनाओं की समीक्षा लंबित है।"]'::jsonb, 'Crime & Law', 'World', 3, 11, 2, 0, 0, 27, 'center', 69, NULL, NULL, '{"left": {"count": 3, "sources": ["Al Jazeera English", "The Telegraph (India)", "The Washington Post"], "owners": ["ABP Group", "Al Jazeera English", "The Washington Post"]}, "center": {"count": 11, "sources": ["Associated Press", "CBS News", "Euronews", "NBC News", "NDTV", "Outlook India", "Reuters", "The Economic Times", "The New Indian Express", "The Statesman", "The Times of India", "The Wall Street Journal"], "owners": ["Associated Press", "CBS News", "Euronews", "NBC News", "NDTV", "Outlook India", "Reuters", "The New Indian Express", "The Statesman", "The Wall Street Journal", "Times Group"]}, "right": {"count": 2, "sources": ["The Jerusalem Post", "The Pioneer"], "owners": ["The Jerusalem Post", "The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["Emphasized the Pentagon''s admission of civilian deaths and injuries.", "Highlighted that the operations occurred after the dismantling of an office focused on mitigating civilian casualties."], "center": ["Stressed the specific numbers of civilians killed (153) and wounded (243).", "Noted that the Pentagon \"finally admits\" the civilian toll.", "Mentioned that 15 additional incidents are still under review."], "right": ["Framed the event as U.S. airstrikes in Yemen.", "Stated that over 150 civilians were killed in Yemen in 2025."]}'::jsonb, '{"left": ["नागरिकों की मौत और चोटों की पेंटागन की स्वीकारोक्ति पर जोर दिया।", "इस बात पर प्रकाश डाला कि ये अभियान नागरिक हताहतों को कम करने पर केंद्रित एक कार्यालय को भंग करने के बाद हुए।"], "center": ["मारे गए (153) और घायल (243) नागरिकों की विशिष्ट संख्याओं पर जोर दिया।", "उल्लेख किया कि पेंटागन ने नागरिक हताहतों को \"आखिरकार स्वीकार\" किया।", "उल्लेख किया कि 15 अतिरिक्त घटनाओं की अभी भी समीक्षा की जा रही है।"], "right": ["घटना को यमन में अमेरिकी हवाई हमलों के रूप में प्रस्तुत किया।", "कहा कि 2025 में यमन में 150 से अधिक नागरिक मारे गए।"]}'::jsonb, '[{"source": "The Washington Post", "owner": "The Washington Post", "lean": "left", "language": "en", "url": "https://www.washingtonpost.com/national-security/2026/08/11/nearly-400-civilians-killed-wounded-us-strikes-yemen-last-year", "headline": "Pentagon report reveals steep civilian toll of Trump’s Yemen campaign"}, {"source": "The Wall Street Journal", "owner": "The Wall Street Journal", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMilwFBVV95cUxQT05yMERoZXIxSzBEaGNETmVsYktrZmRwWk1nVEE1azdkbDFjMWhra01lR2dtcWpWakpCOVY1RDAtTzBwa1lJWVdBTHA0TG1waUJzeDFpMWc1ZlU5YU0zZUZPc2NiTFlIcWJ6TXJHTmt3cC1WRTdObzBwdWt5OGpXUzBHbjVRajlNUUVVejVKYXNoeEZNd2hv?oc=5", "headline": "U.S. Strikes on Yemen Last Year Killed and Wounded Hundreds, Pentagon Finds"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/news/defence/us-military-operations-killed-153-civilians-in-2025-pentagon-says/articleshow/133170424.cms", "headline": "US military operations killed 153 civilians in 2025 , Pentagon says"}, {"source": "The Telegraph (India)", "owner": "ABP Group", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "US military operations killed 153 civilians in 2025, Pentagon assessment says"}, {"source": "NDTV", "owner": "NDTV", "lean": "center", "language": "en", "url": "https://www.ndtv.com/world-news/us-military-operations-killed-153-civilians-wounded-243-in-2025-pentagon-11898261", "headline": "US Military Operations Killed 153 Civilians, Wounded 243 In 2025: Pentagon"}, {"source": "Reuters", "owner": "Reuters", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMizAFBVV95cU