s.google.?oc=5", "headline": "Yemen faces highest risk of returning to war since 2022 truce, UN warns"}, {"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Is Yemen Sliding Back Into War? Houthi Attacks Raise UN Alarm"}, {"source": "The Statesman", "owner": "The Statesman", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "UN envoy delivers grim warning: Yemen closer to all-out war than at any point since 2022 truce"}, {"source": "The Jerusalem Post", "owner": "The Jerusalem Post", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMiXEFVX3lxTE5rd2R4T0RJYXhidlN3UEkwcFozWXBTWGhWNW9JSjIta3prSGpLWWg2SHhoekVBMVRtcldmYmhTS3NCQ29QamxoZkdFTlZUQ0VLNGZHZzJvNjlTUXpK?oc=5", "headline": "Yemen facing escalation from Houthi attacks on Red Sea shipping, UN envoy warns"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMi_?oc=5", "headline": "''Unjustified detention'': UN warns Yemen could slide back into wider war as U.S. envoy blasts Houthis"}, {"source": "NBC News", "owner": "NBC News", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMipwFBVV95cUxPdlNvMy1tb0tzdG1TZUl6aVZFUjN0ejdBS3QwWHhUUWp3VmdySWJ2MU40ajREMmRCLS0tRlFTeDNicGl1d04tLXNiSlpIR0ExYUpIMnNDX3kxX0FCQmdzM1I2eXlXZWZ1bm9McURWMk5EM3E4ZDg0WTRacTRyc3RZV2F2Y2FJbW1wa3RJNmVrWmhQTmVyeDhmWk9XMGdqYzlZbnQwYmZwcw?oc=5", "headline": "U.S. strikes killed 153 civilians in Yemen while targeting Houthis last year, Pentagon says"}], "coverage": {"left": {"count": 3, "sources": ["Al Jazeera English", "The Telegraph (India)", "The Washington Post"], "owners": ["ABP Group", "Al Jazeera English", "The Washington Post"]}, "center": {"count": 11, "sources": ["Associated Press", "CBS News", "Euronews", "NBC News", "NDTV", "Outlook India", "Reuters", "The Economic Times", "The New Indian Express", "The Statesman", "The Times of India", "The Wall Street Journal"], "owners": ["Associated Press", "CBS News", "Euronews", "NBC News", "NDTV", "Outlook India", "Reuters", "The New Indian Express", "The Statesman", "The Wall Street Journal", "Times Group"]}, "right": {"count": 2, "sources": ["The Jerusalem Post", "The Pioneer"], "owners": ["The Jerusalem Post", "The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 17, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://img.etimg.com/thumb/msid-133170462,width-1200,height-630,imgsize-193244,overlay-etdefence/articleshow.jpg', FALSE, FALSE, 'llm', NULL, NULL, NULL, '2026-08-16T00:35:21.877052'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, content_complete = EXCLUDED.content_complete, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13473, 'SEBI Proposes Wider Foreign Investor Access to Commodity Derivatives', 'सेबी ने कमोडिटी डेरिवेटिव्स में विदेशी निवेशकों की पहुंच बढ़ाने का प्रस्ताव दिया', 'The Securities and Exchange Board of India (SEBI) has proposed to allow foreign portfolio investors (FPIs) to trade in non-agricultural commodity derivatives. This move aims to deepen the Indian commodity derivatives market. SEBI Chairman Tuhin Kanta Pandey stated that the regulator has not observed any manipulation in the newly introduced closing auction session, which is designed to align with global standards for establishing closing stock prices. Additionally, SEBI has lowered the stress testing limit for commodity derivatives.', 'भारतीय प्रतिभूति और विनिमय बोर्ड (सेबी) ने विदेशी पोर्टफोलियो निवेशकों (FPIs) को गैर-कृषि कमोडिटी डेरिवेटिव्स में व्यापार करने की अनुमति देने का प्रस्ताव दिया है। इस कदम का उद्देश्य भारतीय कमोडिटी डेरिवेटिव्स बाजार को गहरा करना है। सेबी के चेयरमैन तुहिन कांता पांडे ने कहा कि नियामक ने नए शुरू किए गए क्लोजिंग ऑक्शन सत्र में किसी भी हेरफेर को नहीं देखा है, जिसे समापन स्टॉक की कीमतों को निर्धारित करने के लिए वैश्विक मानकों के अनुरूप बनाया गया है। इसके अतिरिक्त, सेबी ने कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को कम कर दिया है।', '["SEBI proposes allowing foreign portfolio investors to trade in non-agricultural commodity derivatives.", "The initiative aims to expand engagement and deepen India''s commodity derivatives market.", "SEBI Chairman Tuhin Kanta Pandey reported no manipulation in the new closing auction session.", "The closing auction session is a market reform intended to meet international standards.", "SEBI has also reduced the stress testing limit for commodity derivatives."]'::jsonb, '["सेबी ने विदेशी पोर्टफोलियो निवेशकों को गैर-कृषि कमोडिटी डेरिवेटिव्स में व्यापार करने की अनुमति देने का प्रस्ताव दिया है।", "इस पहल का उद्देश्य भारतीय कमोडिटी डेरिवेटिव्स बाजार में भागीदारी का विस्तार करना और उसे गहरा करना है।", "सेबी के चेयरमैन तुहिन कांता पांडे ने नए क्लोजिंग ऑक्शन सत्र में किसी भी हेरफेर की सूचना नहीं दी है।", "क्लोजिंग ऑक्शन सत्र एक बाजार सुधार है जिसका उद्देश्य अंतरराष्ट्रीय मानकों को पूरा करना है।", "सेबी ने कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को भी कम कर दिया है।"]'::jsonb, 'Economy', 'India', 1, 8, 2, 0, 0, 30, 'center', 73, NULL, NULL, '{"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 8, "sources": ["Business Standard", "Business Today", "Deccan Herald", "The Economic Times", "The Financial Express", "The Free Press Journal", "The Hindu BusinessLine", "The Times of India", "The Tribune"], "owners": ["Business Standard", "Deccan Herald", "India Today Group", "Indian Express Group", "The Free Press Journal", "The Hindu Group", "The Tribune", "Times Group"]}, "right": {"count": 2, "sources": ["The Pioneer", "Times Now"], "owners": ["The Pioneer", "Times Now"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"left": ["The sole left-leaning outlet mentions the government considering Merchant Discount Rate (MDR) on select UPI payments to support the ecosystem, a topic not covered by other outlets."], "center": ["Centrist coverage emphasizes SEBI''s proposal to allow foreign portfolio investors (FPIs) in non-agricultural commodity derivatives to deepen the market.", "Multiple centrist outlets highlight SEBI Chairman Tuhin Kanta Pandey''s statements that no manipulation has been observed in the new closing auction session.", "Some centrist reports also mention SEBI lowering the stress testing limit for commodity derivatives."], "right": ["Right-leaning coverage focuses on SEBI Chairman''s assertion that no manipulation has been observed in the newly introduced closing auction session."]}'::jsonb, '{"left": ["एकमात्र वाम-झुकाव वाले आउटलेट ने पारिस्थितिकी तंत्र का समर्थन करने के लिए चुनिंदा यूपीआई भुगतानों पर मर्चेंट डिस्काउंट रेट (एमडीआर) पर विचार करने वाली सरकार का उल्लेख किया है, जो अन्य आउटलेट्स द्वारा कवर नहीं किया गया है।"], "center": ["केंद्रवादी कवरेज बाजार को गहरा करने के लिए गैर-कृषि कमोडिटी डेरिवेटिव्स में विदेशी पोर्टफोलियो निवेशकों (FPIs) की अनुमति देने के सेबी के प्रस्ताव पर जोर देता है।", "कई केंद्रवादी आउटलेट्स सेबी के चेयरमैन तुहिन कांता पांडे के इस बयान पर प्रकाश डालते हैं कि नए क्लोजिंग ऑक्शन सत्र में कोई हेरफेर नहीं देखा गया है।", "कुछ केंद्रवादी रिपोर्टों में सेबी द्वारा कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को कम करने का भी उल्लेख है।"], "right": ["दक्षिणपंथी कवरेज सेबी चेयरमैन के इस दावे पर केंद्रित है कि नए पेश किए गए क्लोजिंग ऑक्शन सत्र में कोई हेरफेर नहीं देखा गया है।"]}'::jsonb, '[{"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "hi", "url": "https://hindi.business-standard.com/markets/sebi-proposes-allowing-fpi-participation-in-non-agricultural-commodity-derivatives-id-543857", "headline": "Commodity Trading : कमोडिटी मार्केट में विदेशी निवेशकों की बढ़ेगी एंट्री ! SEBI ने गैर - कृषि डेरिवेटिव्स के लिए जारी किया नया प्रस्ताव - sebi proposes allowing fpi participation in non agricultural commodity derivatives"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-proposes-to-expand-fpi-play-in-commodities/articleshow/133167595.cms", "headline": "Sebi proposes to expand FPI play in commodities"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI eyes FPIs, mutual funds to deepen commodity derivatives market: Chairman Pandey"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google._SAdsBQVVfeXFMT0VudV9HMnJvTUt6Ni1OSUtCSzk1aVQ4YTJNLVctRklPOUg1UzhmVVUyamVLZG92ckppSWxfdlAzQXFabmdaMUNaYTBWWC1abW1QUzNpS0ZrMU5wM2RXaFRDc1UybTN6NXloYUc0X3pRaUFoTGtOcjM0TXBwdktkTURHa3N6ZUNmQzJZYXkxOHh6UXd0LUJILTdFSDZhdFhwLURORlNpQ1RXVi15b00wVkJsZ01QdmxqQXJnVjJnVmhubjJ1YjFYczY1aEkxNnlBY0t2THJDYXY0M1Jv?oc=5", "headline": "India proposes widening foreign investors'' access to commodities derivatives - bfsi.economictimes.indiatimes.com"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/markets/sebi-sees-no-manipulation-in-stock-closing-auction-chairman-tuhin-kanta-pandey/article71335479.ece", "headline": "SEBI sees no manipulation in stock closing auction: Chairman Tuhin Kanta Pandey"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Closing Auction Session: Did SEBI Put The Cart Before The Horse?"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-manipulation-in-new-cas-despite-participation-concerns/articleshow/133175145.cms", "headline": "Sebi sees no manipulation in closing auction sessions so far, says Tuhin Kanta Pandey"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sebi lowers stress testing limit for commodity derivatives - legal.economictimes.indiatimes.com"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI eyes FPIs, mutual funds to deepen commodity derivatives market: Chairman Pandey - legal.economictimes.indiatimes.com"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MDR on UPI: Enabling law passed, but framework remains unclear - legal.economictimes.indiatimes.com"}, {"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Panel pushes early UPI MDR on high value transactions"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/markets/sebi-sees-no-manipulation-in-closing-auction-so-far/article71336236.ece", "headline": "SEBI sees no manipulation in closing auction so far"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI eyes FPIs, mutual funds to deepen commodity derivatives market: Chairman Pandey"}, {"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMidEFVX3lxTE9ubGpYQnpyd0VSR1RiTmpGRy1wZ2I3aE5fWXRkeEswY2VDRXV6RVZEUWFubHd1VVdWNjVoM1NsVW5NVThyS2Q0SVZJeW5BWUFkSENHUE9Rd3JjSDA0dnJySjBtZXNmWi1rMGFDVGNjanlBaF90?oc=5", "headline": "UPI MDR Returns: What Changes For Merchants Now? - WHAT’S HOT BusinessToday"}, {"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMidEFVX3lxTE0tdjVadll5VXpydkNfdUJkU0NMNTJadFY0VnhlaWlDdVhhRlZoWVdWMUJEUlBERXVlb3htOHV5NzJKWDYtcVNJVXQ5cXo5SzViSVprVm4wWGFwdVNqSGpuX1JSTGNpN25lXzA4N0J2T01YQmEz?oc=5", "headline": "SEBI Chief Tuhin Kanta Pandey’s 4-Point Plan To Transform India’s Commodity Markets - WHAT’S HOT BusinessToday"}, {"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI Chief Tuhin Kanta Pandey’s 4-Point Plan To Transform India’s Commodity Markets"}, {"source": "Times Now", "owner": "Times Now", "lean": "right", "language": "en", "url": "https://news.google.?oc=5", "headline": "Not Observed Any Manipulation In Newly Introduced Closing Auction Session: SEBI Chief"}, {"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "hi", "url": "https://hindi.business-standard.com/markets/sebi-calls-meeting-over-low-mutual-fund-participation-in-closing-action-session-id-544151", "headline": "SEBI Closing Auction Session| Tuhin Kanta Pandey : क्लोजिंग एक्शन सेशन में म्युचुअल फंड्स की कम भागीदारी , सेबी ने बुलाई बैठक - sebi calls meeting over low mutual fund participation in closing action session"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-cas-manipulation-eyes-more-participation/articleshow/133195469.cms", "headline": "Sebi sees no CAS manipulation, eyes more participation"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/et-front/sebi-sees-no-cas-manipulation-eyes-more-participation/articleshow/133193158.cms", "headline": "Sebi Sees No CAS Manipulation , Eyes More Participation"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMitwFBVV95cUxOellmb1FXN21yV0xxRFJIR3QzVm5ZeHhXcXpiQ1NaQ1FfNTlxeG1NQmdReEpmYzBMQVF2WEdrdktTWFhxYlRtRTFNOVZSdzlreGF2bUVNSnRWZGptbVl4b0lLUmczX2xjUTVDekZyOTFsZHFyLWFvVlZfSng5SzlLdDl4TXBXSHF1TWZWNDRvNGdBYjN5a1oxVDN6RzlUQnd2NVVyLTBic0Y5QS04UDVOWHJYWHBITDA?oc=5", "headline": "SEBI Chairman Says No Manipulation Seen in New Closing Auction System"}, {"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Closing Auction System is transparent, says Sebi Chairman Pandey"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://dailypioneer.com/news/no-manipulation-observed-in-closing-auction-sessions-sebi-chairman", "headline": "SEBI Chairman Says No Manipulation Seen in New Closing Auction System"}, {"source": "Deccan Herald", "owner": "Deccan Herald", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Parliamentary panel for expeditious introduction of calibrated MDR on high-value transactions"}, {"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "Government weighs MDR on select UPI payments to support ecosystem"}, {"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MCX: JP Morgan, UBS and Jefferies turn bullish as FPI access opens a new volume opportunity"}, {"source": "The Times of India", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://timesofindia.indiatimes.com/business/india-business/mdr-on-upi-soon-parliamentary-panel-recommends-expeditious-introduction-on-high-value-transactions/articleshow/133204726.cms", "headline": "MDR on UPI soon? Parliamentary Panel recommends expeditious introduction on high-value transactions"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "UPI MDR Could Return On High-Value Transactions As Govt Mulls Tiered Incentives"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/ubs-upgrades-mcx-rating-to-buy-with-rs-3800-target-price-can-it-boost-the-stock/articleshow/133203886.cms", "headline": "UBS upgrades MCX rating to Buy with Rs 3,800 target price: Can it boost the stock?"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sebi lowers stress testing limit for commodity derivatives"}]'::jsonb, '{"title": "SEBI Proposes Wider Foreign Investor Access to Commodity Derivatives", "summary": "The Securities and Exchange Board of India (SEBI) has proposed to allow foreign portfolio investors (FPIs) to trade in non-agricultural commodity derivatives. This move aims to deepen the Indian commodity derivatives market. SEBI Chairman Tuhin Kanta Pandey stated that the regulator has not observed any manipulation in the newly introduced closing auction session, which is designed to align with global standards for establishing closing stock prices. Additionally, SEBI has lowered the stress testing limit for commodity derivatives.", "summary_points": ["SEBI proposes allowing foreign portfolio investors to trade in non-agricultural commodity derivatives.", "The initiative aims to expand engagement and deepen India''s commodity derivatives market.", "SEBI Chairman Tuhin Kanta Pandey reported no manipulation in the new closing auction session.", "The closing auction session is a market reform intended to meet international standards.", "SEBI has also reduced the stress testing limit for commodity derivatives."], "title_hi": "सेबी ने कमोडिटी डेरिवेटिव्स में विदेशी निवेशकों की पहुंच बढ़ाने का प्रस्ताव दिया", "summary_hi": "भारतीय प्रतिभूति और विनिमय बोर्ड (सेबी) ने विदेशी पोर्टफोलियो निवेशकों (FPIs) को गैर-कृषि कमोडिटी डेरिवेटिव्स में व्यापार करने की अनुमति देने का प्रस्ताव दिया है। इस कदम का उद्देश्य भारतीय कमोडिटी डेरिवेटिव्स बाजार को गहरा करना है। सेबी के चेयरमैन तुहिन कांता पांडे ने कहा कि नियामक ने नए शुरू किए गए क्लोजिंग ऑक्शन सत्र में किसी भी हेरफेर को नहीं देखा है, जिसे समापन स्टॉक की कीमतों को निर्धारित करने के लिए वैश्विक मानकों के अनुरूप बनाया गया है। इसके अतिरिक्त, सेबी ने कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को कम कर दिया है।", "summary_points_hi": ["सेबी ने विदेशी पोर्टफोलियो निवेशकों को गैर-कृषि कमोडिटी डेरिवेटिव्स में व्यापार करने की अनुमति देने का प्रस्ताव दिया है।", "इस पहल का उद्देश्य भारतीय कमोडिटी डेरिवेटिव्स बाजार में भागीदारी का विस्तार करना और उसे गहरा करना है।", "सेबी के चेयरमैन तुहिन कांता पांडे ने नए क्लोजिंग ऑक्शन सत्र में किसी भी हेरफेर की सूचना नहीं दी है।", "क्लोजिंग ऑक्शन सत्र एक बाजार सुधार है जिसका उद्देश्य अंतरराष्ट्रीय मानकों को पूरा करना है।", "सेबी ने कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को भी कम कर दिया है।"], "framing": {"left": ["The sole left-leaning outlet mentions the government considering Merchant Discount Rate (MDR) on select UPI payments to support the ecosystem, a topic not covered by other outlets."], "center": ["Centrist coverage emphasizes SEBI''s proposal to allow foreign portfolio investors (FPIs) in non-agricultural commodity derivatives to deepen the market.", "Multiple centrist outlets highlight SEBI Chairman Tuhin Kanta Pandey''s statements that no manipulation has been observed in the new closing auction session.", "Some centrist reports also mention SEBI lowering the stress testing limit for commodity derivatives."], "right": ["Right-leaning coverage focuses on SEBI Chairman''s assertion that no manipulation has been observed in the newly introduced closing auction session."]}, "framing_hi": {"left": ["एकमात्र वाम-झुकाव वाले आउटलेट ने पारिस्थितिकी तंत्र का समर्थन करने के लिए चुनिंदा यूपीआई भुगतानों पर मर्चेंट डिस्काउंट रेट (एमडीआर) पर विचार करने वाली सरकार का उल्लेख किया है, जो अन्य आउटलेट्स द्वारा कवर नहीं किया गया है।"], "center": ["केंद्रवादी कवरेज बाजार को गहरा करने के लिए गैर-कृषि कमोडिटी डेरिवेटिव्स में विदेशी पोर्टफोलियो निवेशकों (FPIs) की अनुमति देने के सेबी के प्रस्ताव पर जोर देता है।", "कई केंद्रवादी आउटलेट्स सेबी के चेयरमैन तुहिन कांता पांडे के इस बयान पर प्रकाश डालते हैं कि नए क्लोजिंग ऑक्शन सत्र में कोई हेरफेर नहीं देखा गया है।", "कुछ केंद्रवादी रिपोर्टों में सेबी द्वारा कमोडिटी डेरिवेटिव्स के लिए तनाव परीक्षण सीमा को कम करने का भी उल्लेख है।"], "right": ["दक्षिणपंथी कवरेज सेबी चेयरमैन के इस दावे पर केंद्रित है कि नए पेश किए गए क्लोजिंग ऑक्शन सत्र में कोई हेरफेर नहीं देखा गया है।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://hindibusinessstandard.imagibyte.sortdcdn.net/wp-content/uploads/2026/04/SEBI-4.jpg", "sources": [{"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "hi", "url": "https://hindi.business-standard.com/markets/sebi-proposes-allowing-fpi-participation-in-non-agricultural-commodity-derivatives-id-543857", "headline": "Commodity Trading : कमोडिटी मार्केट में विदेशी निवेशकों की बढ़ेगी एंट्री ! SEBI ने गैर - कृषि डेरिवेटिव्स के लिए जारी किया नया प्रस्ताव - sebi proposes allowing fpi participation in non agricultural commodity derivatives"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-proposes-to-expand-fpi-play-in-commodities/articleshow/133167595.cms", "headline": "Sebi proposes to expand FPI play in commodities"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI eyes FPIs, mutual funds to deepen commodity derivatives market: Chairman Pandey"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google._SAdsBQVVfeXFMT0VudV9HMnJvTUt6Ni1OSUtCSzk1aVQ4YTJNLVctRklPOUg1UzhmVVUyamVLZG92ckppSWxfdlAzQXFabmdaMUNaYTBWWC1abW1QUzNpS0ZrMU5wM2RXaFRDc1UybTN6NXloYUc0X3pRaUFoTGtOcjM0TXBwdktkTURHa3N6ZUNmQzJZYXkxOHh6UXd0LUJILTdFSDZhdFhwLURORlNpQ1RXVi15b00wVkJsZ01QdmxqQXJnVjJnVmhubjJ1YjFYczY1aEkxNnlBY0t2THJDYXY0M1Jv?oc=5", "headline": "India proposes widening foreign investors'' access to commodities derivatives - bfsi.economictimes.indiatimes.com"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.com/markets/sebi-sees-no-manipulation-in-stock-closing-auction-chairman-tuhin-kanta-pandey/article71335479.ece", "headline": "SEBI sees no manipulation in stock closing auction: Chairman Tuhin Kanta Pandey"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Closing Auction Session: Did SEBI Put The Cart Before The Horse?"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-manipulation-in-new-cas-despite-participation-concerns/articleshow/133175145.cms", "headline": "Sebi sees no manipulation in closing auction sessions so far, says Tuhin Kanta Pandey"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sebi lowers stress testing limit for commodity derivatives - legal.economictimes.indiatimes.com"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "SEBI eyes FPIs, mutual funds to deepen commodity derivatives market: Chairman Pandey - legal.economictimes.indiatimes.com"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MDR on UPI: Enabling law passed, but framework remains unclear - legal.economictimes.indiatimes.com"}, {"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Panel pushes early UPI MDR on high value transactions"}, {"source": "The Hindu BusinessLine", "owner": "The Hindu Group", "lean": "center", "language": "en", "url": "https://www.thehindubusinessline.co