 में म्युचुअल फंड्स की कम भागीदारी , सेबी ने बुलाई बैठक - sebi calls meeting over low mutual fund participation in closing action session"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-cas-manipulation-eyes-more-participation/articleshow/133195469.cms", "headline": "Sebi sees no CAS manipulation, eyes more participation"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/et-front/sebi-sees-no-cas-manipulation-eyes-more-participation/articleshow/133193158.cms", "headline": "Sebi Sees No CAS Manipulation , Eyes More Participation"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMitwFBVV95cUxOellmb1FXN21yV0xxRFJIR3QzVm5ZeHhXcXpiQ1NaQ1FfNTlxeG1NQmdReEpmYzBMQVF2WEdrdktTWFhxYlRtRTFNOVZSdzlreGF2bUVNSnRWZGptbVl4b0lLUmczX2xjUTVDekZyOTFsZHFyLWFvVlZfSng5SzlLdDl4TXBXSHF1TWZWNDRvNGdBYjN5a1oxVDN6RzlUQnd2NVVyLTBic0Y5QS04UDVOWHJYWHBITDA?oc=5", "headline": "SEBI Chairman Says No Manipulation Seen in New Closing Auction System"}, {"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Closing Auction System is transparent, says Sebi Chairman Pandey"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://dailypioneer.com/news/no-manipulation-observed-in-closing-auction-sessions-sebi-chairman", "headline": "SEBI Chairman Says No Manipulation Seen in New Closing Auction System"}, {"source": "Deccan Herald", "owner": "Deccan Herald", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Parliamentary panel for expeditious introduction of calibrated MDR on high-value transactions"}, {"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "Government weighs MDR on select UPI payments to support ecosystem"}, {"source": "The Financial Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "MCX: JP Morgan, UBS and Jefferies turn bullish as FPI access opens a new volume opportunity"}, {"source": "The Times of India", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://timesofindia.indiatimes.com/business/india-business/mdr-on-upi-soon-parliamentary-panel-recommends-expeditious-introduction-on-high-value-transactions/articleshow/133204726.cms", "headline": "MDR on UPI soon? Parliamentary Panel recommends expeditious introduction on high-value transactions"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "UPI MDR Could Return On High-Value Transactions As Govt Mulls Tiered Incentives"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://economictimes.indiatimes.com/markets/stocks/news/ubs-upgrades-mcx-rating-to-buy-with-rs-3800-target-price-can-it-boost-the-stock/articleshow/133203886.cms", "headline": "UBS upgrades MCX rating to Buy with Rs 3,800 target price: Can it boost the stock?"}, {"source": "The Economic Times", "owner": "Times Group", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Sebi lowers stress testing limit for commodity derivatives"}], "coverage": {"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 8, "sources": ["Business Standard", "Business Today", "Deccan Herald", "The Economic Times", "The Financial Express", "The Free Press Journal", "The Hindu BusinessLine", "The Times of India", "The Tribune"], "owners": ["Business Standard", "Deccan Herald", "India Today Group", "Indian Express Group", "The Free Press Journal", "The Hindu Group", "The Tribune", "Times Group"]}, "right": {"count": 2, "sources": ["The Pioneer", "Times Now"], "owners": ["The Pioneer", "Times Now"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 12, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://hindibusinessstandard.imagibyte.sortdcdn.net/wp-content/uploads/2026/04/SEBI-4.jpg', FALSE, FALSE, 'llm', NULL, NULL, NULL, '2026-08-13T08:57:38.940017'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, content_complete = EXCLUDED.content_complete, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, content_complete, storyline_id, published_at, created_at) VALUES (13476, 'Zambia Votes in Presidential Election Amid Economic Challenges', 'जाम्बिया में आर्थिक चुनौतियों के बीच राष्ट्रपति चुनाव के लिए मतदान', 'Zambians cast their ballots on Thursday in a general election where incumbent President Hakainde Hichilema is widely expected to win a second term. The election is seen as a test of his economic reforms amidst voter frustration over the cost of living, inflation, and debt restructuring. Key issues shaping the vote include economic recovery, youth turnout, and women''s representation. The election also takes place against the backdrop of a continuing feud between Hichilema and the family of his predecessor, Edgar Lungu.', 'जाम्बिया में गुरुवार को एक आम चुनाव में मतदान हुआ, जहाँ निवर्तमान राष्ट्रपति हकाइंदे हिचिलेमा से दूसरे कार्यकाल के लिए व्यापक रूप से जीतने की उम्मीद है। यह चुनाव व्यापक आर्थिक निराशा, मुद्रास्फीति और ऋण पुनर्गठन के बीच उनके आर्थिक सुधारों की परीक्षा है। मतदान को आकार देने वाले प्रमुख मुद्दों में आर्थिक सुधार, युवा मतदान और महिलाओं का प्रतिनिधित्व शामिल है। यह चुनाव पूर्व राष्ट्रपति एडगर लुंगु के परिवार के साथ हिचिलेमा के चल रहे झगड़े की पृष्ठभूमि में भी हो रहा है।', '["Zambians voted on Thursday in a general election.", "President Hakainde Hichilema is seeking a second term.", "The election is testing his economic reforms against voter frustration over the cost of living and inflation.", "Key issues include economic recovery, youth turnout, and women''s representation.", "The election is also influenced by the legacy of former president Edgar Lungu."]'::jsonb, '["जाम्बिया में गुरुवार को एक आम चुनाव के लिए मतदान हुआ।", "राष्ट्रपति हकाइंदे हिचिलेमा दूसरे कार्यकाल की तलाश में हैं।", "यह चुनाव जीवन यापन की लागत और मुद्रास्फीति से जूझ रहे मतदाताओं के सामने उनके आर्थिक सुधारों की परीक्षा ले रहा है।", "प्रमुख मुद्दों में आर्थिक सुधार, युवा मतदान और महिलाओं का प्रतिनिधित्व शामिल है।", "यह चुनाव पूर्व राष्ट्रपति एडगर लुंगु की विरासत की पृष्ठभूमि में भी हो रहा है।"]'::jsonb, 'Politics', 'World', 4, 7, 1, 0, 0, 28, 'center', 58, NULL, NULL, '{"left": {"count": 4, "sources": ["Al Jazeera English", "The Guardian", "The Independent", "The New York Times"], "owners": ["Al Jazeera English", "The Guardian", "The Independent", "The New York Times"]}, "center": {"count": 7, "sources": ["Associated Press", "BBC News", "Business Insider", "Deutsche Welle", "France 24", "The Economist", "The Print"], "owners": ["Associated Press", "BBC News", "Business Insider", "Deutsche Welle", "France 24", "The Economist", "The Print"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["The sole centrist outlet highlighted President Hichilema''s expected win and the economic challenges testing his reforms.", "This coverage noted the election is a test of his reforms against voter frustration over the cost of living and opposition parties seeking to capitalize on discontent."], "right": ["The sole right-leaning outlet framed the election around the incumbent president seeking a second term."]}'::jsonb, '{"center": ["एकमात्र मध्यमार्गी आउटलेट ने राष्ट्रपति हिचिलेमा की अपेक्षित जीत और उनके सुधारों को परखने वाली आर्थिक चुनौतियों पर प्रकाश डाला।", "इस कवरेज में उल्लेख किया गया है कि यह चुनाव जीवन यापन की लागत से मतदाताओं की निराशा और असंतोष का लाभ उठाने की कोशिश कर रही विपक्षी पार्टियों के खिलाफ उनके सुधारों की परीक्षा है।"], "right": ["एकमात्र दक्षिणपंथी आउटलेट ने चुनाव को निवर्तमान राष्ट्रपति द्वारा दूसरे कार्यकाल की तलाश के इर्द-गिर्द केंद्रित किया।"]}'::jsonb, '[{"source": "Deutsche Welle", "owner": "Deutsche Welle", "lean": "center", "language": "en", "url": "https://www.dw.com/en/key-issues-in-zambias-2026-general-election/a-78320087", "headline": "Key issues in Zambia 2026 general election"}, {"source": "Al Jazeera English", "owner": "Al Jazeera English", "lean": "left", "language": "en", "url": "https://www.aljazeera.com/news/2026/8/12/zambia-to-vote-as-economic-hardship-tests-government-reforms?traffic_source=rss", "headline": "Zambia to vote as economic hardship tests government reforms"}, {"source": "Deutsche Welle", "owner": "Deutsche Welle", "lean": "center", "language": "en", "url": "https://www.dw.com/en/zambia-s-2026-election-key-issues-to-watch/a-78320087?maca=en-rss-en-world-4025-xml-mrss", "headline": "Zambia''s 2026 election: Key issues to watch"}, {"source": "The New York Times", "owner": "The New York Times", "lean": "left", "language": "en", "url": "https://news.google.com/rss/articles/CBMilgFBVV95cUxPc3NVb2haY0NxZmQ1UnhGVnJ2RGdKSFJtMW1RMk8zXzNFamR3QzI1SzBueXNJR1pSc0xTSUNDeVRaVnZyMENBZ3RxY2M0T3l3N3l2NnlBcHlLUXJ0WUNBZEcxSDJWaFoxSlYwcHpBdkxOcXpQYjhpaFVZaGZOUGVkOThQNTVzVnVhOTRLdnEwR1BEcTAyanc?oc=5", "headline": "Zambia Prepares for High-Stakes Election as President Seeks New Term"}, {"source": "The Economist", "owner": "The Economist", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMimwFBVV95cUxPWlFnb2pqRXVFZ1VCYkx2TVBrc2g2cUQ5anNjMjA4ZEJnSDBIdkQ2SFJqYlZtaGxfVjNMaXlEbUNkSmczb0NGdU1IWHF4WTRIdlFTbmxGVHBUcGtnUjZvNXBJRnZLdkZOcW54dDNuVmllSlZjanE2OFlsYlB0SGM3YnZ2T05sRkpkTF81VVgzeWVCV0oyYm83RGdVZw?oc=5", "headline": "Zambia’s election is a test of metal"}, {"source": "France 24", "owner": "France 24", "lean": "center", "language": "en", "url": "https://www.france24.com/en/africa/20260813-zambia-heads-to-polls-with-president-hichilema-expected-to-win-second-term", "headline": "Zambia heads to polls with President Hichilema expected to win second term"}, {"source"